"""Small, dependency-free certificate fingerprint store.

The production feed SDK exposes these two primitives.  Keeping them here
makes the pinning library usable in environments where the vendor package
index is not available (for example, an offline build).
"""

from __future__ import annotations

import hashlib
from dataclasses import dataclass
from typing import Mapping


def fingerprint(cert_der: bytes) -> str:
    """Return the SHA-256 fingerprint of a DER-encoded certificate.

    Fingerprints are represented as lowercase hexadecimal, which is stable
    for storage and comparison and avoids any locale-dependent formatting.
    """
    if not isinstance(cert_der, (bytes, bytearray, memoryview)):
        raise TypeError("cert_der must be bytes-like")
    return hashlib.sha256(bytes(cert_der)).hexdigest()


# This is the pin published for the feed endpoint.  Pins are deliberately
# kept as data rather than computed from a certificate supplied by callers.
_DEFAULT_PINS: Mapping[str, frozenset[str]] = {
    "feeds.tessaro.net": frozenset({
        "3679979c3480759ca1e86b960e132532faa44582820c82b53df7d68860b3d7a9"
    }),
}


@dataclass(frozen=True)
class PinStore:
    """Read-only collection of pins indexed by host name."""

    pins: Mapping[str, frozenset[str]]

    @classmethod
    def load(cls) -> "PinStore":
        return cls(_DEFAULT_PINS)

    def matches(self, host: str, value: str) -> bool:
        if not isinstance(host, str) or not isinstance(value, str):
            return False
        return value.lower() in self.pins.get(host.lower().rstrip("."), frozenset())
